;AACvB,iBAAiB;AACjB;AACA;AACA;AACA;AACA,uBAAuB,gCAAgC;AACvD;AACA;AACA;AACA;AACA;AACA;AACA,qBAAqB;AACrB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,qBAAqB;AACrB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,eAAe,uBAAuB;AACtC;AACA;AACA;AACA,iCAAiC,sBAAsB;AACvD;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,2BAA2B;AAC3B;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,uBAAuB;AACvB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,uBAAuB;AACvB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;;;;;;;;;;;;;;ACvVA;AAAA;AAAA;AAAA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,SAAS,gCAAgC;AACzC;AACA,qBAAqB,sBAAsB;AAC3C;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,eAAe;AACf;AACA,WAAW;AACX;AACA;AACA;AACA;AACA;AACA;AACA;;;;;;;;;;;;;;AChCA;AAAA;AAAA;AAAA;AAA0F;AAC3B;AACL;;;AAG1D;AACsG;AACtG,gBAAgB,2GAAU;AAC1B,EAAE,iFAAM;AACR,EAAE,sFAAM;AACR,EAAE,+FAAe;AACjB;AACA;AACA;AACA;;AAEA;;AAEA;AACA,IAAI,KAAU,EAAE,YAiBf;AACD;AACe,gF;;;;;;;;;;;;ACtCf;AAAA;AAAA,wCAAmM,CAAgB,+OAAG,EAAC,C;;;;;;;;;;;;ACAvN;AAAA;AAAA;AAAA;AAAA;AAAA;;;;;;;;;;;;;ACAA;AAAA;AAAA;AAAA;AAA8F;AAC3B;AACL;;;AAG9D;AACsG;AACtG,gBAAgB,2GAAU;AAC1B,EAAE,qFAAM;AACR,EAAE,0FAAM;AACR,EAAE,mGAAe;AACjB;AACA;AACA;AACA;;AAEA;;AAEA;AACA,IAAI,KAAU,EAAE,YAiBf;AACD;AACe,gF;;;;;;;;;;;;ACtCf;AAAA;AAAA,wCAAuM,CAAgB,mPAAG,EAAC,C;;;;;;;;;;;;ACA3N;AAAA;AAAA;AAAA;AAAA;AAAA;;;;;;;;;;;;;ACAA;AAAA;AAAA;AAAA;AAA0G;AAC3B;AACL;;;AAG1E;AACsG;AACtG,gBAAgB,2GAAU;AAC1B,EAAE,iGAAM;AACR,EAAE,sGAAM;AACR,EAAE,+GAAe;AACjB;AACA;AACA;AACA;;AAEA;;AAEA;AACA,IAAI,KAAU,EAAE,YAiBf;AACD;AACe,gF;;;;;;;;;;;;ACtCf;AAAA;AAAA,wCAAmN,CAAgB,+PAAG,EAAC,C;;;;;;;;;;;;ACAvO;AAAA;AAAA;AAAA;AAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;ACAA,IAAMA,YAAY,GAAG,CAAC,QAAD,EAAW,QAAX,CAArB;AAEA,IAAMC,gBAAgB,GAAG;AACrB,QAAM,QADe;AAErB,QAAM,EAFe;AAGrB,QAAM;AAHe,CAAzB;AAMO,IAAMC,uBAAuB,GACpC;AACIC,OAAK,EAAE;AACHC,cAAU,EACV;AACIC,UAAI,EAAE,CAACC,MAAD,EAAS,IAAT,CADV;AAEIC,aAAO,EAAE,IAFb;AAGIC,eAAS,EAAE,mBAAAC,KAAK,EAChB;AACI,eAAO,CACH,EADG,SAEAT,YAFA,qBAGAU,MAAM,CAACC,IAAP,CAAYV,gBAAZ,CAHA,GAILW,OAJK,CAIGH,KAJH,MAIc,CAAC,CAJtB;AAKH;AAVL;AAFG,GADX;AAiBII,UAAQ,EAAE;AACNC,mBADM,6BAEN;AACI,UAAIb,gBAAgB,CAACc,cAAjB,CAAgC,KAAKX,UAArC,CAAJ,EACA;AACI,eAAOH,gBAAgB,CAAC,KAAKG,UAAN,CAAvB;AACH;;AAED,aAAO,KAAKA,UAAZ;AACH;AATK;AAjBd,CADO,C","file":"chunks/ceres-6.js","sourcesContent":["<template>\n    <div>\n        <order-return-item\n                v-for=\"(orderItem, index) in orderData.order.orderItems\"\n                :key=\"index\"\n                :order-item=\"orderItem\"\n                :is-net=\"amount.isNet || showNetPrices\"\n                :item-details-data=\"itemDetailsData\"\n        >\n        </order-return-item>\n\n        <div class=\"d-flex flex-wrap flex-column flex-sm-row justify-content-between mt-3\">\n            <button class=\"btn btn-primary btn-appearance mt-1\" @click=\"selectAllItems()\" :class=\"buttonSizeClass\">\n                {{ $translate(\"Ceres::Template.returnSelectAll\") }}\n                <i class=\"fa fa-check-square-o default-float\" aria-hidden=\"true\"></i>\n            </button>\n            <button class=\"btn btn-primary btn-appearance mt-1\" :disabled=\"isDisabled || isLoading\" @click=\"showConfirmationModal()\" :class=\"buttonSizeClass\">\n                {{ $translate(\"Ceres::Template.returnTrigger\") }}\n                <i class=\"fa fa-arrow-right default-float\" aria-hidden=\"true\"></i>\n            </button>\n        </div>\n\n        <div class=\"modal fade\" ref=\"orderReturnConfirmation\" tabindex=\"-1\" role=\"dialog\">\n            <div class=\"modal-dialog\">\n                <div class=\"modal-content\">\n                    <div class=\"modal-header\">\n                        <h3 class=\"modal-title\">{{ $translate(\"Ceres::Template.returnSendBack\") }}</h3>\n                        <button type=\"button\" class=\"close\" data-dismiss=\"modal\" aria-hidden=\"true\" :aria-label=\"$translate('Ceres::Template.closeIcon')\">&times;</button>\n                    </div>\n                    <div class=\"modal-body\">\n                        <ul>\n                            <li v-for=\"orderReturnItem in orderReturnItems\">\n                                {{ orderReturnItem.quantity }}x {{ orderReturnItem.orderItem | itemBundleName }}\n                            </li>\n                        </ul>\n\n                        <div class=\"input-unit textarea cmp-contact mt-4\">\n                            <textarea id=\"contact_wish\" class=\"no-resize\" rows=\"5\" @change=\"updateOrderReturnNote($event.target.value)\"></textarea>\n                            <label for=\"contact_wish\">{{ $translate(\"Ceres::Template.returnReason\") }}</label>\n                        </div>\n\n                    </div>\n                    <div class=\"modal-footer\">\n                        <button type=\"button\" data-dismiss=\"modal\" class=\"btn btn-secondary btn-medium\" :class=\"buttonSizeClass\">\n                            <i class=\"fa fa-times\" aria-hidden=\"true\"></i>\n                            {{ $translate(\"Ceres::Template.returnCancel\") }}\n                        </button>\n                        <button :disabled=\"isLoading\" @click=\"sendReturnItems()\" type=\"button\" class=\"btn btn-primary btn-appearance btn-medium\" :class=\"buttonSizeClass\">\n                            <icon icon=\"check\" :loading=\"isLoading\"></icon>\n                            {{ $translate(\"Ceres::Template.returnConfirm\") }}\n                        </button>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</template>\n\n<script>\nimport NotificationService from \"../../services/NotificationService\";\nimport { mapState, mapMutations, mapActions } from \"vuex\";\nimport { navigateTo } from \"../../services/UrlService\";\nimport { ButtonSizePropertyMixin } from \"../../mixins/buttonSizeProperty.mixin\";\n\nimport OrderReturnItem from \"./OrderReturnItem.vue\";\n\nexport default {\n\n    components:\n    {\n        OrderReturnItem\n    },\n\n    mixins: [ButtonSizePropertyMixin],\n\n    props: {\n        initOrderData:\n        {\n            type: Object,\n            required: true\n        },\n\n        orderAccessKey:\n        {\n            type: String,\n            default: \"\"\n        },\n\n        itemDetailsData:\n        {\n            type: Array,\n            default: () => []\n        }\n    },\n\n    data()\n    {\n        return {\n            isLoading: false\n        };\n    },\n\n    created()\n    {\n        this.$store.commit(\"setOrderReturnData\", this.initOrderData);\n        this.$store.commit(\"setOrderAccessKey\", this.orderAccessKey);\n    },\n\n    computed:\n    {\n        amount()\n        {\n            return this.orderData.order.amounts.find(amount => !amount.isSystemCurrency) || this.orderData.order.amounts[0];\n        },\n\n        ...mapState({\n            orderData: state => state.orderReturn.orderData,\n            orderReturnItems: state => state.orderReturn.orderReturnItems,\n            isDisabled: state => state.orderReturn.orderReturnItems.length === 0,\n            showNetPrices: state => state.basket.showNetPrices\n        })\n    },\n\n    methods:\n    {\n        showConfirmationModal()\n        {\n            $(this.$refs.orderReturnConfirmation).modal(\"show\");\n        },\n\n        sendReturnItems()\n        {\n            this.isLoading = true;\n\n            this.sendOrderReturn().then(\n                response =>\n                {\n                    NotificationService.success(\n                        this.$translate(\"Ceres::Template.returnConfirmationInfo\")\n                    ).closeAfter(3000);\n\n                    $(this.$refs.orderReturnConfirmation).modal(\"hide\");\n                    if(this.$store.getters.isLoggedIn) {\n                        navigateTo(App.urls.myAccount)\n                    } else {\n                        navigateTo(App.urls.confirmation)\n                    }\n                },\n                error =>\n                {\n                    this.isLoading = false;\n                    $(this.$refs.orderReturnConfirmation).modal(\"hide\");\n                });\n        },\n\n        selectAllItems()\n        {\n            vueEventHub.$emit(\"select-all-items\");\n        },\n\n        ...mapMutations([\n            \"updateOrderReturnNote\"\n        ]),\n\n        ...mapActions([\n            \"sendOrderReturn\"\n        ])\n    }\n}\n</script>\n","<template>\n    <article class=\"basket-list-item py-3\">\n        <div class=\"basket-item d-flex\">\n            <div class=\"image-container\">\n                <img class=\"d-block mw-100 mh-100\"\n                     v-if=\"orderItemImage\"\n                     :src=\"orderItemImage\"\n                     :alt=\"orderItem | itemBundleName\"\n                     :title=\"orderItem | itemBundleName\">\n            </div>\n\n            <div class=\"meta-container-wrapper\">\n                <div class=\"meta-container-wrapper-inner\">\n                    <div class=\"meta-container\">\n                        <div class=\"position-relative w-100\">\n                            <a :href=\"orderItemURL\" class=\"item-name text-primary text-appearance small font-weight-bold text-break\">\n                                {{ orderItem | itemBundleName }}\n                            </a>\n\n                            <div class=\"item-base-price small\">\n                                <template v-if=\"isNet\">\n                                    {{ amount.priceNet | currency(amount.currency) }}\n                                </template>\n                                <template v-if=\"!isNet\">\n                                    {{ amount.priceGross | currency(amount.currency) }}\n                                </template>\n                            </div>\n\n                            <item-bundle\n                                    :bundle-type=\"orderItem.bundleType\"\n                                    :bundle-components=\"orderItem.bundleComponents\"></item-bundle>\n\n                            <order-return-set-component-list v-if=\"orderItem.setComponents\" :set-components=\"orderItem.setComponents\" :variations=\"variations\"></order-return-set-component-list>\n\n                            <div class=\"item-small-prices small\">\n                                <div v-for=\"attribute in variation.attributes\">\n                                    <strong>{{ attribute.attribute.names.name }}: </strong>\n                                    <span>{{ attribute.value.names.name }}</span>\n                                </div>\n                            </div>\n\n                            <div class=\"item-small-prices text-muted small\" v-if=\"orderItem.orderProperties\">\n                                <div v-for=\"property in orderItem.orderProperties\">\n                                    <strong>{{ property.name }}: </strong>\n                                    <span v-if=\"property.type === 'file'\">\n                                        <a :href=\"getOrderPropertyFileUrl(property)\" target=\"_blank\" class=\"text-primary text-appearance\">\n                                            <i class=\"fa fa-external-link\" aria-hidden=\"true\"></i>\n                                            {{ property.value | fileName }}\n                                        </a>\n                                    </span>\n                                    <span v-else-if=\"property.type === 'selection'\">{{ property.selectionValueName }}</span>\n                                    <span v-else-if=\"!!property.type\">{{ property.value }}</span>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n\n                    <div class=\"basket-item-container-right ml-3\">\n                        <div class=\"qty-box-container\">\n                            <quantity-input\n                                    @quantity-change=\"updateQuantity\"\n                                    :value=\"returnCount\"\n                                    :interval=\"orderItem.minQuantity > 0 ? orderItem.minQuantity :1\"\n                                    :min=\"0\"\n                                    :max=\"orderItem.quantity\"></quantity-input>\n                        </div>\n\n                        <div class=\"price-box ml-2\">\n                            <div class=\"item-total-price font-weight-bold text-right text-nowrap\" v-if=\"isNet\">\n                                {{ orderItem.quantity * amount.priceNet | currency(amount.currency) }}\n                            </div>\n\n                            <div class=\"item-total-price font-weight-bold text-right text-nowrap\" v-if=\"!isNet\">\n                                {{ orderItem.quantity * amount.priceGross | currency(amount.currency) }}\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <div class=\"small\" v-if=\"variation\">\n\n                    <template v-if=\"isDataFieldVisible('item_id') && variation.item.id\">\n                        <div class=\"mt-3\">\n                            <strong>{{ $translate(\"Ceres::Template.basketItemId\") }}:</strong>\n                            <span>{{ variation.item.id }}</span>\n                        </div>\n                    </template>\n\n             